CREATE TABLE inbox_ingest_events (
            event_id INTEGER PRIMARY KEY AUTOINCREMENT,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            inbox_filename TEXT NOT NULL,
            content_hash TEXT,
            status TEXT NOT NULL,
